  'Skin / Dermat':['Acne & Acne Scar Treatment','Pigmentation & Melasma','Skin Brightening','Anti-Aging Treatments','Laser Treatments','Chemical Peels','Skin Infections','General Dermatology','HydraFacial','Carbon Laser Facial','Skin Rejuvenation','Skin Tightening','Mole/Wart Removal','Anti-Tan Treatment','MNRF','Microneedling'],
  'Hair Patch':['Hair Patch Consultation','Hair Patch Maintenance'],
  Hair:['Hair Fall Treatment','Hair Regrowth Therapy','PRP Hair Treatment','GFC Hair Treatment','Mesotherapy','Dandruff & Scalp Treatment','Stem Cell Hair Therapy','Hair Transplant Consultation','Non-Surgical Hair Replacement'],
  'HT (Hair Transplant)':['Hair Transplant (FUE)','Hair Transplant (DHI)','Hair Transplant (FUT)','Beard Transplant'],
  Laser:['Laser Hair Removal (LHR)','Q-Switch Laser','Tattoo Removal'],
  Aesthetics:['Botox','Dermal Fillers','Botox + Fillers Combo'],
  'Life Rise':['Lifestyle Counseling','Nutritional Guidance','Preventive Health Programs','Health & Wellness Coaching','Lifestyle Disease Management','LIFE RISE – GLP Program','LIFE RISE – Nutrition Program','LIFE RISE – Gut Health Program'],
  'Online Consultation':['Online Consultation'],
};
const treatmentCategories = Object.keys(categoryInterests);
const treatmentInterests = computed(()=>[...new Set(selectedCategories.value.flatMap(category=>categoryInterests[category]||[]))]);
const leadDraft = ref({}), selectedCategories=ref([]), selectedInterests=ref([]), actionType=ref(''), historyRows=computed(()=>detail.value?.workflow_hint?.legacy_events||[]);
const stepComplete=computed(()=>[!!leadDraft.value.source,!!leadDraft.value.first_name&&!!leadDraft.value.gender,!!leadDraft.value.city,selectedCategories.value.length>0,!!(leadDraft.value.weight||leadDraft.value.medical_history),!!followup.value.sub_status,!!actionType.value]);
const progress=computed(()=>Math.round(stepComplete.value.filter(Boolean).length*100/steps.length));
const callSeconds=ref(0), callRunning=ref(false); let callInterval;
const callClock=computed(()=>`${String(Math.floor(callSeconds.value/60)).padStart(2,'0')}:${String(callSeconds.value%60).padStart(2,'0')}`);
function startCall(){if(callRunning.value||!detail.value)return;window.dispatchEvent(new CustomEvent('life-convox-native',{detail:{type:'life-convox-call',lead_id:detail.value.name,onResult:result=>{if(!result.success){actionError.value=result.message||'Call could not be started.';return;}callRunning.value=true;callSeconds.value=0;callInterval=setInterval(()=>callSeconds.value++,1000);}}}));}
function openPhone(){window.dispatchEvent(new CustomEvent('life-convox-native',{detail:{type:'life-convox-open',lead_id:detail.value?.name}}));}
function stopCall(){callRunning.value=false;clearInterval(callInterval);}
function goStep(index){activeStep.value=index;document.getElementById('cc-form-step-'+index)?.scrollIntoView({behavior:'smooth',block:'start'});}
let controller, detailController, generation = 0, detailGeneration = 0;
const columns = [
  { key: 'name', label: 'Lead ID' }, { key: 'lead_name', label: 'Client' },
  { key: 'mobile_no', label: 'Phone', value: r => maskPhone(r.mobile_no) },
  { key: 'branch', label: 'Branch', value: r => r.branch || r.lead_assign_to_branch },
  { key: 'lead_owner', label: 'Agent' }, { key: 'custom_cc_sub_status', label: 'Status', value: r => r.custom_cc_sub_status || r.status },
  { key: 'custom_appointment_date_and_time', label: 'Appointment' }, { key: 'custom_next_followup_date', label: 'Next follow-up' },
];
const pages = computed(() => searching.value ? page.value + (more.value ? 1 : 0) : Math.max(1, Math.ceil(visibleLeads.value.length / 10)));
const visibleLeads=computed(()=>rows.value.filter(row=>(!queueStatus.value||(row.custom_cc_stage||row.status)===queueStatus.value)&&(!queueOwner.value||row.lead_owner===queueOwner.value)&&(!queueSubStatus.value||(queueSubStatus.value==='No Response / Not Reachable'?['No Response','Not Reachable'].includes(row.custom_cc_sub_status):row.custom_cc_sub_status===queueSubStatus.value))&&(!queueCategory.value||String(row.custom_treatment_interests||'').toLowerCase().includes(queueCategory.value.toLowerCase()))&&(!queueSearch.value.trim()||[row.name,row.lead_name,row.mobile_no,row.branch,row.lead_owner].some(v=>String(v||'').toLowerCase().includes(queueSearch.value.trim().toLowerCase())))));
// Capture applied filters so changing a draft cannot mix pagination cohorts.
watch([queueOwner,queueStatus,queueSubStatus,queueCategory,queueSearch],()=>page.value=1);
let filters = {};
function apply() {
  error.value = '';
  if (query.value.trim() && query.value.trim().length < 2) { error.value = 'Enter at least two characters to search.'; return; }
  if (!query.value.trim() && (!from.value || !to.value || from.value > to.value)) { error.value = 'Choose a valid date range.'; return; }
  filters = query.value.trim() ? { query: query.value.trim() } : { from_date: from.value, to_date: to.value, date_mode: mode.value };
  searching.value = !!filters.query;
  applied.value = filters.query ? 'Search across permitted history: ' + filters.query : `${from.value} → ${to.value} · ${mode.value}`;
  load(1);
}
async function load(nextPage) {
  const token = ++generation; controller?.abort(); controller = new AbortController();
  page.value = nextPage; loading.value = true; error.value = ''; rows.value = []; total.value = 0;
  try {
    const data = await ccCall('cc_get_leads', { ...filters, start: searching.value ? (nextPage - 1) * 20 : 0 }, controller.signal);
    if(!searching.value){
      const cohorts=await Promise.all(['followup','appointment'].filter(value=>value!==filters.date_mode).map(date_mode=>ccCall('cc_get_leads',{...filters,date_mode,start:0},controller.signal)));
      createdIds.value=new Set((data.rows||[]).map(row=>row.name));
      appointmentCohort.value=filters.date_mode==='appointment'?(data.rows||[]):cohorts[filters.date_mode==='followup'?0:1]?.rows||[];
      data.rows=[...new Map([...(data.rows||[]),...cohorts.flatMap(cohort=>cohort.rows||[])].map(row=>[row.name,row])).values()];
      if(data.truncated||cohorts.some(cohort=>cohort.truncated)) error.value='The selected range exceeds the lead limit. Choose a shorter range to view all leads.';
    }
    if (token !== generation) return;
    if(searching.value){createdIds.value=new Set((data.rows||[]).map(row=>row.name));appointmentCohort.value=(data.rows||[]).filter(row=>row.custom_appointment_date_and_time)}
    rows.value = data.rows || []; total.value = data.total || 0; more.value = !!data.more; scoped.value = !!data.scoped_to_owner; contactManager.value=!!data.contact_manager;
  } catch (e) { if (token === generation && e.name !== 'AbortError') error.value = e.message; }
  finally { if (token === generation) loading.value = false; }
}
async function openDetail(row) {
  window.dispatchEvent(new CustomEvent('life-convox-native',{detail:{type:'life-convox-select',lead_id:row.name}}));
  stopCall();
  detailController?.abort(); detailController = new AbortController(); const token = ++detailGeneration;
  detail.value = row; detailError.value = ''; detailLoading.value = true; actionError.value=''; actionNotice.value=matchNotice.value; matchNotice.value=''; followup.value={stage:'',sub_status:'',status:'',next_followup:'',conclusion:'',remarks:''}; actionType.value=''; activeStep.value=0; selectedView.value='followup';
  try {
    const data = await ccCall('cc_get_leads', { query: row.name, detail: 1 }, detailController.signal);
    if (token !== detailGeneration) return;
    const found = data.rows?.find(item => item.name === row.name);
    if (!found) throw new Error('This lead is no longer available to your account.');
    contactManager.value=!!data.contact_manager; detail.value = found; initLeadDraft(found);
  } catch (e) { if (token === detailGeneration && e.name !== 'AbortError') detailError.value = e.message; }
  finally { if (token === detailGeneration) detailLoading.value = false; }
}
function closeDetail() { stopCall(); detailGeneration++; detailController?.abort(); detail.value=null; selectedView.value='queue'; }
function initLeadDraft(row) {
  const dateTime = String(row.custom_next_followup_date||'').replace(' ','T').slice(0,16);
  const interests=String(row.custom_treatment_interests||'').split(';').map(x=>x.trim()).filter(Boolean);
  selectedCategories.value=treatmentCategories.filter(x=>interests.includes(x));
  selectedInterests.value=String(row.custom_specific_interests||'').split(';').map(x=>x.trim()).filter(Boolean);
  leadDraft.value={lead_owner:row.lead_owner||'',consultant:row.consultant||'',first_name:row.first_name||row.lead_name||'',email_id:row.email_id||'',age:row.age||'',gender:row.gender||'',city:row.city||'',source:row.source||'',custom_media:row.custom_media||'',custom_posting_date:row.custom_posting_date||'',branch:row.branch||'',lead_assign_to_branch:row.lead_assign_to_branch||'',enquired_for:row.enquired_for||'',phone:row.phone||'',custom_marital_status:row.custom_marital_status||'',custom_no_of_kids:row.custom_no_of_kids||'',custom_delivery_type:row.custom_delivery_type||'',custom_breastfeeding:row.custom_breastfeeding||'',weight:row.weight||'',height:row.height||'',custom_bmi:row.custom_bmi||'',custom_target_weight:row.custom_target_weight||'',medical_history:row.medical_history||'',custom_current_medication:row.custom_current_medication||'',custom_previous_attempts:row.custom_previous_attempts||'',custom_hospitalized:row.custom_hospitalized||'',custom_cc_stage:row.custom_cc_stage||row.status||'UNTOUCHED',custom_cc_sub_status:row.custom_cc_sub_status||'',custom_next_followup_date:dateTime,custom_conclusion_remark:row.custom_conclusion_remark||'',custom_remarks:row.custom_remarks||'',custom_chat_script:row.custom_chat_script||''};
  followup.value={stage:row.custom_cc_stage||row.status||'UNTOUCHED',sub_status:row.custom_cc_sub_status||'',status:row.status||'',next_followup:dateTime,conclusion:row.custom_conclusion_remark||'',remarks:String(row.custom_remarks||'').replace(/\[CC_PROFILE_V1\][\s\S]*?\[\/CC_PROFILE_V1\]/g,'').trim()};
}
function toggleCategory(category){selectedCategories.value=selectedCategories.value.includes(category)?selectedCategories.value.filter(x=>x!==category):[...selectedCategories.value,category];}
function toggleInterest(interest){selectedInterests.value=selectedInterests.value.includes(interest)?selectedInterests.value.filter(x=>x!==interest):[...selectedInterests.value,interest];}
function stageFromOutcome(outcome){if(['Appointment Booked','Existing Client','Walked In & Booked'].includes(outcome))return 'SUCCESS';if(['Not Interested','Other clinic','Joined Competition','Do Not Contact'].includes(outcome))return 'LOST';if(['Invalid Number','Wrong number','Not in Service','Job enquiry','Franchise Lead','Junk/Wrong Call','Not Enquired','TNA','NID'].includes(outcome))return 'INVALID';if(['Very Positive','Call & Confirm','Callback: Scheduled','Price Negotiation','Out Station','Walked In: Not Booked','Get Back','No Response','Not Reachable','Switch OFF','Call Disconnected','Appointment no response'].includes(outcome))return 'FOLLOW-UP';return followup.value.stage||'FOLLOW-UP';}
function openCreate() { createError.value=''; createDialog.value?.showModal(); }
async function createLead() {
  createBusy.value=true; createError.value='';
  try {
    const values={...createForm.value};
    const result=await ccCall('cc_create_lead',{values:JSON.stringify(values)});
    const matched=result.duplicate;
    createDialog.value?.close(); createForm.value={first_name:'',mobile_no:'',email_id:'',age:'',gender:'',city:'',source:'',branch:'',enquired_for:'',custom_remarks:''};
    const id=matched?.name||result.created;
    if(!id) throw new Error('The lead was not created. Please retry.');
    filters={query:id};searching.value=true;applied.value=matched?`Matched existing client · ${id}`:`Created lead · ${id}`;query.value=id;
    await load(1);
    matchNotice.value=matched?`This mobile number already belongs to ${id} (${matched.lead_name||'existing client'}). Opened the existing lead.`:'';
    await openDetail({name:id,lead_name:matched?.lead_name||values.first_name});
  } catch(e) { createError.value=e.message; }
  finally { createBusy.value=false; }
}
async function saveFollowup(payload) {
  if(!detail.value) return;
  actionType.value=payload.nextAction;
  const outcome=followup.value.sub_status||leadDraft.value.custom_cc_sub_status;
  const stage=followup.value.stage||stageFromOutcome(outcome);
  savingFollowup.value=true; actionError.value=''; actionNotice.value='';
  try {
    const values={...leadDraft.value,custom_cc_stage:stage,custom_cc_sub_status:outcome,custom_treatment_interests:selectedCategories.value.join('; '),custom_specific_interests:selectedInterests.value.join('; '),custom_next_followup_date:followup.value.next_followup,custom_conclusion_remark:followup.value.conclusion,custom_remarks:followup.value.remarks+"\n[CC_PROFILE_V1]"+JSON.stringify(payload.profile)+"[/CC_PROFILE_V1]"};
    if(actionType.value==='pipeline') { values.custom_pipeline_date_and_time=followup.value.next_followup; values.custom_cc_stage='PIPELINE'; }
    await ccCall('cc_update_lead',{lead:detail.value.name,values:JSON.stringify(values),attempt:JSON.stringify({result:payload.result,reason:payload.reason,expected_modified:detail.value.modified})});
    const portalStatuses={'UNTOUCHED':'Lead','FOLLOW-UP':'Followup','SUCCESS':'Interested','LOST':'Not interested','INVALID':'Not Response','PIPELINE':'Followup'};
    await ccCall('cc_add_lead_followup',{lead:detail.value.name,cc_stage:values.custom_cc_stage,cc_sub_status:values.custom_cc_sub_status,status:portalStatuses[values.custom_cc_stage]||'Followup',next_followup:values.custom_next_followup_date,conclusion:values.custom_conclusion_remark,remarks:followup.value.remarks});
    actionNotice.value=actionType.value==='book'?'Lead saved. Choose the appointment slot next.':'Lead update and call outcome saved.';
    const id=detail.value.name;
    const refreshed=await ccCall('cc_get_leads',{query:id,detail:1},detailController?.signal);
    detail.value=refreshed.rows?.find(item=>item.name===id)||detail.value;
    initLeadDraft(detail.value);
    await load(page.value);
    if(actionType.value==='book') { await booking.value.open(id,leadDraft.value.branch); }
  } catch(e) { actionError.value=e.message; }
  finally { savingFollowup.value=false; }
}
function quickRange(period){
 const now=new Date(today+'T12:00:00Z'),stamp=d=>d.toISOString().slice(0,10);
 if(period==='yesterday'){now.setUTCDate(now.getUTCDate()-1);from.value=to.value=stamp(now)}
 else if(period==='month'||period==='lastmonth'){const offset=period==='lastmonth'?-1:0;from.value=stamp(new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth()+offset,1)));to.value=stamp(new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth()+offset+1,0)))}
 else from.value=to.value=today;
 query.value='';apply()
}
onMounted(apply);
onUnmounted(() => { generation++; detailGeneration++; controller?.abort(); detailController?.abort(); clearInterval(callInterval); });
</script>
<template>
<section class="cc-native cc-native-shell cc-erp-root cc-dashboard-vue">
  <header class="hdr portal-module-toolbar"><button class="hdr-btn hdr-burger" aria-label="Toggle menu" @click="$event.currentTarget.closest('.cc-erp-root').querySelector('.sidebar').classList.toggle('collapsed')">☰</button><div class="hdr-brand" hidden><div class="logo">L</div><div><div class="bn">🎧 LIFE CALL CENTRE AGENT DASHBOARD &gt;&gt;</div><div class="bs">CC Command ERP</div></div></div><div class="hdr-center"><div class="search-wrap"><span class="si">🔍</span><input v-model="globalSearch" type="search" placeholder="Search treatments, scripts, FAQs, leads..."><div v-if="globalMatches.length" class="search-results" style="display:block"><button v-for="item in globalMatches" :key="item.title" class="search-item" @click="chooseGlobal(item)">{{item.title}}</button></div></div></div><RouterLink id="cc-reports-link" :to="{name:'ccvisit'}">CC-Reports</RouterLink><div class="hdr-attend"><span class="att-io att-in">LIFE <b>PORTAL</b></span></div><div class="hdr-right"><div class="agent-info"><div class="an">{{session?.full_name||'Agent Name'}}</div><div class="ai">Call Center</div></div><div class="agent-avatar">{{String(session?.full_name||'A').slice(0,1).toUpperCase()}}</div></div></header>
  <div class="body-wrap"><nav class="sidebar"><div class="nav-section-label">Main</div><button class="nav-item" :class="{active:selectedView==='dashboard'}" @click="showView('dashboard')"><span class="ni">📊</span>Dashboard</button><button class="nav-item" :class="{active:selectedView==='queue'}" @click="showView('queue')"><span class="ni">📋</span>My Lead Queue <span class="nav-badge">{{total}}</span></button><button class="nav-item" :class="{active:selectedView==='followup'}" @click="showView('followup')"><span class="ni">📞</span>Lead Follow-Up Form</button><button class="nav-item" :class="{active:selectedView==='appointments'}" @click="showView('appointments')"><span class="ni">📅</span>Appointments</button><div class="nav-section-label">Management (TL)</div><button class="nav-item" :class="{active:selectedView==='tl'}" @click="showView('tl')"><span class="ni">👥</span>TL Control Panel</button><button class="nav-item" :class="{active:selectedView==='reports'}" @click="showView('reports')"><span class="ni">📈</span>Reports</button><div class="nav-section-label">Knowledge Base</div><button class="nav-item" :class="{active:selectedView==='scripts'}" @click="showView('scripts')"><span class="ni">💬</span>Call Scripts</button><button class="nav-item" :class="{active:selectedView==='faq'}" @click="showView('faq')"><span class="ni">❓</span>FAQ / Knowledge Base</button><button class="nav-item" :class="{active:selectedView==='treatments'}" @click="showView('treatments')"><span class="ni">💉</span>Treatment Guide</button><button class="nav-item" :class="{active:selectedView==='objections'}" @click="showView('objections')"><span class="ni">🛡️</span>Objection Handling</button><button class="nav-item" :class="{active:selectedView==='branches'}" @click="showView('branches')"><span class="ni">🏥</span>Branch Directory</button><button class="nav-item" :class="{active:selectedView==='doctors'}" @click="showView('doctors')"><span class="ni">👨‍⚕️</span>Doctor Directory</button></nav><main class="main">
  <form v-if="['dashboard','queue','tl','reports','appointments'].includes(selectedView)" id="cc-quick-range" class="cc-rangebar" @submit.prevent="query='';apply()"><strong>📅 Lead Date Range</strong><button type="button" class="btn btn-sm cc-qr-btn" @click="quickRange('today')">Today</button><button type="button" class="btn btn-sm cc-qr-btn" @click="quickRange('yesterday')">Yesterday</button><button type="button" class="btn btn-sm cc-qr-btn" @click="quickRange('month')">This Month</button><button type="button" class="btn btn-sm cc-qr-btn" @click="quickRange('lastmonth')">Last Month</button><label>From <input v-model="from" type="date"></label><label>To <input v-model="to" type="date"></label><label>Filter <select id="cc-date-mode" v-model="mode"><option value="created">Created</option><option value="posting">Posting</option><option value="updated">Updated</option></select></label><button class="btn btn-g btn-sm cc-qr-btn" data-range="apply">Apply</button><button type="button" class="btn btn-gy btn-sm" @click="quickRange('today')">Clear</button></form>
  <div class="page-breadcrumb">Home <span>›</span><span class="cur">{{({dashboard:'Dashboard',queue:'My Lead Queue',followup:'Lead Follow-Up Form',appointments:'Appointments',tl:'TL Control Panel',reports:'Reports',scripts:'Call Scripts',faq:'FAQ / Knowledge Base',treatments:'Treatment Guide',objections:'Objection Handling',branches:'Branch Directory',doctors:'Doctor Directory'})[selectedView]||'Dashboard'}}</span><button v-if="['dashboard','queue','followup'].includes(selectedView)" class="btn btn-g btn-sm" @click="openCreate">＋ Add new lead</button></div>
  <form v-if="selectedView==='followup'&&!detail" class="cc-date-toolbar" @submit.prevent="apply"><strong>Lead Follow-Up Form</strong><input v-model="query" type="search" placeholder="Search client name, phone or lead ID"><button class="cc-primary">Find lead</button><button type="button" @click="showView('queue')">Back to queue</button></form>
  <p v-if="error" class="cc-error" role="alert">{{ error }} <button @click="load(page)">Retry</button></p>
  <div class="page-section active" :id="({dashboard:'page-dashboard',queue:'page-my-leads',followup:'page-followup',appointments:'page-appointment',tl:'page-tl-panel'})[selectedView]||'page-'+selectedView">
  <div v-if="selectedView==='dashboard'">
    <div class="stat-grid">
      <button class="stat-card s-blue" @click="showView('queue')"><div class="sl">Assigned Today</div><div class="sv">{{total}}</div><div class="ss">{{scoped?'Leads assigned to you':'All team leads in range'}} · click to view</div></button>
      <button class="stat-card s-gold" @click="queueStatus='UNTOUCHED';showView('queue')"><div class="sl">Untouched</div><div class="sv">{{stageCounts.UNTOUCHED||0}}</div><div class="ss">Call now! · click to view</div></button>
      <button class="stat-card s-teal" @click="queueStatus='FOLLOW-UP';showView('queue')"><div class="sl">Follow-Up Due</div><div class="sv">{{stageCounts['FOLLOW-UP']||0}}</div><div class="ss">Scheduled callbacks · click to view</div></button>
      <button class="stat-card s-gold" @click="queueStatus='';queueSubStatus='No Response / Not Reachable';showView('queue')"><div class="sl">No Response / Not Reachable</div><div class="sv">{{noResponseCount}}</div><div class="ss">Combined · click to view</div></button>
      <button class="stat-card s-red" @click="queueStatus='';queueSubStatus='Invalid Number';showView('queue')"><div class="sl">Invalid</div><div class="sv">{{invalidCount}}</div><div class="ss">Invalid number · click to view</div></button>
      <button class="stat-card s-red" @click="queueStatus='';queueSubStatus='NID';showView('queue')"><div class="sl">NID</div><div class="sv">{{nidCount}}</div><div class="ss">NID · click to view</div></button>
      <button class="stat-card s-green grp-card" @click="groupPanel=groupPanel==='appt'?'':'appt'"><div class="sl">Appointments ▾</div><div class="sv">{{appointmentRows.length}}</div><div class="ss">{{sameDayAppointments}} same-day · {{olderLeadAppointments}} older · tap to break down</div></button>
      <button class="stat-card s-teal grp-card" @click="groupPanel=groupPanel==='converted'?'':'converted'"><div class="sl">Converted ▾</div><div class="sv">{{convertedRows.length}}</div><div class="ss">{{sameDayConverted}} same-day · {{olderConverted}} older · tap to break down</div></button>
      <button class="stat-card s-red" @click="queueStatus='SUCCESS';showView('queue')"><div class="sl">Conversion Rate</div><div class="sv">{{total?Math.round((stageCounts.SUCCESS||0)*100/total):0}}%</div><div class="ss">{{stageCounts.SUCCESS||0}} of {{total}} leads · click to view</div></button>
    </div>
    <div id="dash-group-panel" v-if="groupPanel" class="group-panel"><div class="stat-grid"><button v-for="item in (groupPanel==='appt'?[{label:'Appointments Booked',sub:'Scheduled in range',val:appointmentRows.length},{label:'Created & Appt Today',sub:'Same-day leads',val:sameDayAppointments},{label:'Older Lead, Appt Today',sub:'Older leads, appt today',val:olderLeadAppointments}]:[{label:'Converted',sub:'Visited & booked',val:convertedRows.length},{label:'Created & Converted Today',sub:'Same-day leads',val:sameDayConverted},{label:'Older Lead Converted',sub:'Older leads, converted',val:olderConverted}])" :key="item.label" class="stat-card s-green" @click="showView(groupPanel==='appt'?'appointments':'queue')"><div class="sl">{{item.label}}</div><div class="sv">{{item.val}}</div><div class="ss">{{item.sub}} · click to view</div></button></div></div>
    <div class="cc-grid-2">
      <section class="card"><header class="card-hdr">📋 My Lead Queue <span class="badge">{{visibleLeads.filter(x=>['UNTOUCHED','FOLLOW-UP'].includes(x.custom_cc_stage||x.status)).length}}</span><button class="btn btn-sm btn-gold" @click="showView('queue')">View All</button></header><div id="dash-queue-list" class="card-body"><div v-if="loading" class="cc-loading-row">Loading leads…</div><article v-for="row in dashQueueRows" :key="row.name" class="queue-item wf-qrow" tabindex="0" @click="openDetail(row)" @keydown.enter="openDetail(row)"><div class="wf-q-main"><div class="wf-q-l1"><strong class="wf-q-name">{{row.lead_name||row.name}}</strong><span class="wf-f br">🏥 {{row.branch||row.lead_assign_to_branch||'No branch'}}</span><span class="wf-f ag">👤 {{row.lead_owner||'Unassigned'}}</span><span class="wf-f st">{{row.custom_cc_stage||row.status}}</span><span v-if="row.custom_cc_sub_status" class="wf-f sub">{{row.custom_cc_sub_status}}</span><span v-if="row.custom_appointment_status" class="wf-f ap">{{row.custom_appointment_status}}</span><span v-if="row.custom_next_followup_date" class="wf-f fu">📅 {{row.custom_next_followup_date}}</span></div><div class="wf-q-l2">{{maskPhone(row.mobile_no)}}<template v-if="row.source"> · <b>{{row.source}}</b></template><template v-if="row.custom_treatment_interests"> · {{row.custom_treatment_interests}}</template></div></div><div class="wf-q-side"><button class="wf-q-btn" @click.stop="openDetail(row)">📞 Call &amp; Update</button></div></article><p v-if="!loading&&!dashQueueRows.length" class="cc-empty-state">No leads in queue. Great work! 🎉</p></div></section>
      <section class="card"><header class="card-hdr">⏰ Today’s Follow-Up Reminders <span class="badge">{{rows.filter(x=>x.custom_next_followup_date).length}}</span></header><div id="dash-reminders" class="card-body"><template v-for="(bucket,key) in [{key:'overdue',label:'⚠️ Overdue',color:'#C62828'},{key:'today',label:'📅 Today',color:'#E65100'},{key:'upcoming',label:'⏭️ Upcoming',color:'#1565C0'},{key:'nodate',label:'❓ No date set',color:'#78909C'}]" :key="key"><div v-if="reminderBuckets[bucket.key].length" class="wf-reminder-group" :style="{background:bucket.color}"><span>{{bucket.label}}</span><b>{{reminderBuckets[bucket.key].length}}</b></div><article v-for="row in reminderBuckets[bucket.key]" :key="row.name" class="queue-item wf-qrow" tabindex="0" @click="openDetail(row)" @keydown.enter="openDetail(row)"><div class="wf-q-main"><div class="wf-q-l1"><strong class="wf-q-name">{{row.lead_name||row.name}}</strong><span class="wf-f st">{{row.custom_cc_stage||row.status}}</span><span v-if="row.custom_cc_sub_status" class="wf-f sub">{{row.custom_cc_sub_status}}</span><span v-if="row.custom_next_followup_date" class="wf-f fu">📅 {{row.custom_next_followup_date}}</span></div><div class="wf-q-l2">{{maskPhone(row.mobile_no)}} · {{row.custom_conclusion_remark||row.custom_cc_sub_status||'Follow-up scheduled'}}</div></div><div class="wf-q-side"><button class="wf-q-btn" @click.stop="openDetail(row)">Follow Up</button></div></article></template><p v-if="!reminderRows.length" class="cc-empty-state">No reminders 👍</p></div></section>
    </div>
    <section v-if="!scoped" class="card"><header class="card-hdr">📊 Today’s Team Performance (TL View)</header><div class="card-body"><div class="tbl-wrap"><table><thead><tr><th>Agent</th><th>Assigned</th><th>Called</th><th>Appointments</th><th>Conversion %</th><th>Status</th></tr></thead><tbody><tr v-for="agent in agentRows" :key="agent.name"><td><strong>{{agent.name}}</strong></td><td>{{agent.total}}</td><td>—</td><td>{{rows.filter(r=>r.lead_owner===agent.name&&r.custom_appointment_date_and_time).length}}</td><td>{{agent.total?Math.round(agent.success*100/agent.total):0}}%</td><td><span class="pill p-green">active</span></td></tr><tr v-if="!agentRows.length"><td colspan="6">No team data for this range.</td></tr></tbody></table></div></div></section>
  </div>
  <template v-else-if="selectedView==='queue'"><div class="cc-queue-toolbar"><span class="cc-status-line">{{ loading ? 'Loading leads…' : searching ? rows.length + ' matches on this page' : total + ' matching leads' }} · {{ applied }}<span v-if="scoped"> · Your assigned leads</span></span><span class="cc-quick-links"><button @click="load(page)">↻ Refresh</button></span></div><div id="cc-ml-filterbar" class="cc-queue-filters"><input id="cc-ml-search" v-model="queueSearch" type="search" placeholder="🔍 Search leads by name, phone or Lead ID"><select v-if="!scoped" id="cc-ml-owner" v-model="queueOwner"><option value="">All Owners</option><option v-for="owner in [...new Set(rows.map(row=>row.lead_owner).filter(Boolean))]" :key="owner">{{owner}}</option></select><select id="cc-ml-status" v-model="queueStatus"><option value="">All Status</option><option>UNTOUCHED</option><option>FOLLOW-UP</option><option>SUCCESS</option><option>LOST</option><option>INVALID</option></select><select v-model="queueSubStatus"><option value="">All Call Results</option><option>No Response / Not Reachable</option><option v-for="result in callOutcomes" :key="result">{{result}}</option></select><select v-model="queueCategory"><option value="">All Categories</option><option v-for="category in treatmentCategories" :key="category">{{category}}</option></select><button class="btn btn-gy btn-sm" @click="queueOwner='';queueStatus='';queueSubStatus='';queueCategory='';queueSearch=''">Clear</button></div><section class="card"><header class="card-hdr">📋 My Lead Queue <span class="badge">{{visibleLeads.length}}</span></header><div id="my-leads-list" class="card-body"><p class="cc-status-line">Showing {{visibleLeads.length? (page-1)*10+1:0}}–{{Math.min(page*10,visibleLeads.length)}} of {{visibleLeads.length}} leads</p><article v-for="row in visibleLeads.slice((page-1)*10,page*10)" :key="row.name" class="queue-item wf-qrow"><div class="wf-q-main"><div class="wf-q-l1"><strong class="wf-q-name">{{row.lead_name||row.name}}</strong><span class="wf-f ag">👤 {{row.lead_owner||'Unassigned'}}</span><span class="wf-f st">{{row.custom_cc_stage||row.status}}</span><span v-if="row.custom_cc_sub_status" class="wf-f sub">{{row.custom_cc_sub_status}}</span><small>{{row.name}}</small></div><div class="wf-q-l2">📞 {{maskPhone(row.mobile_no)}} · 📍 {{row.city||'—'}} · 📡 {{row.source||'—'}} · 🗓 {{String(row.creation||'').slice(0,10)}} · 📞×{{row.custom_call_count||0}}</div><div class="wf-q-l1"><span v-if="row.custom_treatment_interests" class="wf-f">{{row.custom_treatment_interests}}</span><span v-if="row.branch||row.lead_assign_to_branch" class="wf-f br">🏥 {{row.branch||row.lead_assign_to_branch}}</span><span v-if="row.custom_next_followup_date" class="wf-f fu">📅 {{row.custom_next_followup_date}}</span><span v-if="row.custom_appointment_date_and_time" class="wf-f ap">📅 Appt: {{row.custom_appointment_date_and_time}}</span></div><p v-if="row.custom_conclusion_remark" class="wf-q-l2">💬 {{row.custom_conclusion_remark}}</p></div><div class="wf-q-side"><button class="wf-q-btn" @click="openDetail(row)">📞 Call &amp; Update</button><button class="btn btn-gy btn-sm" @click="viewLead(row)">👁 View</button></div></article><p v-if="!loading&&!visibleLeads.length" class="cc-empty-state">No leads match the selected filter.</p></div></section><CCPager :page="page" :pages="pages" :busy="loading" @change="searching?load($event):page=$event" /></template>
  <template v-else-if="selectedView==='appointments'"><section class="cc-card"><header>📅 Appointments in selected date range <RouterLink :to="{name:'cc-appointments'}">Open booking calendar →</RouterLink></header><p class="cc-note">{{appointmentRows.length}} appointments found · summary is based on leads visible to your account.</p><div class="cc-report-metrics"><div v-for="(count,source) in sourceCounts" :key="source"><strong>{{count}}</strong><span>{{source}}</span></div></div><CCDataTable :columns="columns" :rows="appointmentRows" :busy="loading"><template #actions="{row}"><button @click="openDetail(row)">Open lead</button><RouterLink :to="{name:'cc-appointments',query:{lead:row.name}}">Book / reschedule</RouterLink></template></CCDataTable></section></template>
  <template v-else-if="selectedView==='tl'"><section class="cc-card"><header>👥 Team lead control panel</header><p class="cc-note">Agent totals use the leads visible for the selected period and your account permissions.</p><div class="cc-dashboard-tiles cc-stage-tiles"><button v-for="stage in stages" :key="stage" @click="queueStatus=stage;showView('queue')"><small>{{stage}}</small><strong>{{stageCounts[stage]}}</strong><span>Open matching leads →</span></button></div><h3>Agent performance</h3><table class="cc-simple-table"><thead><tr><th>Agent</th><th>Leads</th><th>Success</th><th>Follow-ups</th><th>Conversion</th></tr></thead><tbody><tr v-for="agent in agentRows" :key="agent.name"><td>{{agent.name}}</td><td>{{agent.total}}</td><td>{{agent.success}}</td><td>{{agent.followups}}</td><td>{{agent.total?Math.round(agent.success*100/agent.total):0}}%</td></tr><tr v-if="!agentRows.length"><td colspan="5">No leads in this date range.</td></tr></tbody></table><h3>All accessible leads</h3><div class="cc-queue-filters"><input v-model="queueSearch" placeholder="Search client, lead ID, owner or branch"><select v-model="queueStatus"><option value="">All status</option><option v-for="stage in stages" :key="stage">{{stage}}</option></select></div><CCDataTable :columns="columns" :rows="visibleLeads" :busy="loading"><template #actions="{row}"><button @click="openDetail(row)">Open</button></template></CCDataTable></section></template>
  <template v-else-if="selectedView==='reports'"><div class="cc-dashboard-tiles cc-stage-tiles"><button v-for="stage in stages" :key="stage" @click="queueStatus=stage;showView('queue')"><small>{{stage}}</small><strong>{{stageCounts[stage]}}</strong><span>{{rows.length?Math.round(stageCounts[stage]*100/rows.length):0}}% of visible leads</span></button><button><small>TOTAL LEADS</small><strong>{{total}}</strong><span>{{applied}}</span></button><button><small>APPOINTMENTS</small><strong>{{appointmentRows.length}}</strong><span>In selected range</span></button></div><div class="cc-dashboard-columns"><section class="cc-card"><header>📊 Lead source report</header><table class="cc-simple-table"><thead><tr><th>Source</th><th>Leads</th><th>Share</th></tr></thead><tbody><tr v-for="[source,count] in sourceCounts" :key="source"><td>{{source}}</td><td>{{count}}</td><td>{{rows.length?Math.round(count*100/rows.length):0}}%</td></tr><tr v-if="!sourceCounts.length"><td colspan="3">No source data in this date range.</td></tr></tbody></table></section><section class="cc-card"><header>📈 Branch performance</header><table class="cc-simple-table"><thead><tr><th>Branch</th><th>Leads</th><th>Success</th></tr></thead><tbody><tr v-for="branch in [...new Set(rows.map(r=>r.branch||r.lead_assign_to_branch||'Unassigned'))]" :key="branch"><td>{{branch}}</td><td>{{rows.filter(r=>(r.branch||r.lead_assign_to_branch||'Unassigned')===branch).length}}</td><td>{{rows.filter(r=>(r.branch||r.lead_assign_to_branch||'Unassigned')===branch&&(r.custom_cc_stage||r.status)==='SUCCESS').length}}</td></tr></tbody></table></section></div><section class="cc-card"><header>🧾 Lead report <button @click="printReport">Print report</button></header><CCDataTable :columns="columns" :rows="rows" :busy="loading" /></section></template>
  <template v-else-if="selectedView==='scripts'"><section id="scripts-area" class="card"><header class="card-hdr">💬 Call Centre Agent Scripts — Master Reference</header><div class="card-body"><div id="script-tabs" class="tab-nav"><button v-for="tab in [{id:'scripts',label:'📋 Call Scripts'},{id:'objections',label:'🛡️ Objection Handling'},{id:'results',label:'📈 Results FAQ'}]" :key="tab.id" class="tab-btn" :class="{on:knowledgeTab===tab.id}" @click="knowledgeTab=tab.id">{{tab.label}}</button></div><div v-if="knowledgeTab==='scripts'" id="tab-scripts" class="tab-pane on"><article v-for="item in scripts" :key="item.title" class="script-card"><div class="sc-title">{{item.icon}} {{item.title}}</div><div class="sc-text" style="white-space:pre-line">{{item.text}}</div><button class="copy-btn" @click="copyText(item.text)">📋 Copy Script</button></article></div><div v-else-if="knowledgeTab==='objections'" id="tab-objections" class="tab-pane on"><details v-for="item in objections" :key="item.obj" class="acc-item"><summary class="acc-hdr">🛡️ Client says: “{{item.obj}}”<span class="acc-icon">▼</span></summary><div class="acc-body"><div class="script-card"><div class="sc-title">Suggested Response</div><div class="sc-text" style="white-space:pre-line">{{item.response}}</div><div class="agent-tip">💡 <strong>Strategy:</strong> {{item.tip}}</div><button class="copy-btn" @click="copyText(item.response)">📋 Copy Response</button></div></div></details></div><div v-else id="tab-results" class="tab-pane on"><div class="script-card"><div class="sc-title">Golden Rule of Results</div><div class="sc-text">Never give a single, rigid number. Instead, explain the timeline and emphasize customization. Frame the variation as a sign of premium medical care.</div></div><details v-for="item in faqs.filter(x=>/result/i.test(x.cat+' '+x.q))" :key="item.q" class="acc-item"><summary class="acc-hdr">{{item.cat}}: {{item.q}}<span class="acc-icon">▼</span></summary><div class="acc-body">{{item.a}}<button class="copy-btn" @click="copyText(item.a)">📋 Copy Answer</button></div></details></div></div></section><p v-if="copyNotice" class="cc-success">{{copyNotice}}</p></template>
  <template v-else-if="selectedView==='faq'"><section id="faq-area" class="card"><header class="card-hdr">❓ FAQ &amp; Knowledge Base<input id="faq-search" v-model="faqSearch" placeholder="Search FAQs..." class="ff-input" style="width:200px;height:28px"></header><div class="card-body"><div id="faq-list"><section v-for="category in [...new Set(filteredFaqs.map(item=>item.cat))]" :key="category" style="margin-bottom:14px"><div class="form-section-title">{{category}}</div><details v-for="item in filteredFaqs.filter(item=>item.cat===category)" :key="item.q" class="acc-item"><summary class="acc-hdr">{{item.q}}<span class="acc-icon">▼</span></summary><div class="acc-body"><p>{{item.a}}</p><button class="copy-btn" @click="copyText(item.a)">📋 Copy Answer</button></div></details></section></div></div></section></template>
  <template v-else-if="selectedView==='treatments'"><section id="treatments-area" class="card"><header class="card-hdr">💉 Treatment Knowledge Base</header><div class="card-body"><details v-for="item in treatments" :key="item.name" class="acc-item"><summary class="acc-hdr">{{item.icon}} {{item.name}}<span class="pill p-blue">{{item.cat}}</span><span class="acc-icon">▼</span></summary><div class="acc-body"><div class="form-grid"><div><div class="form-section-title">Purpose</div><p>{{item.purpose}}</p></div><div><div class="form-section-title">Suitable For</div><p>{{item.suitableFor}}</p></div></div><div class="form-section-title">Benefits</div><p v-for="benefit in item.benefits" :key="benefit">{{benefit}}</p><div class="form-grid"><p><b>Sessions:</b> {{item.sessions}}</p><p><b>Recovery:</b> {{item.recovery}}</p><p><b>Pain Level:</b> {{item.pain}}</p><p><b>Results:</b> {{item.results}}</p></div><p><b>Cannot take:</b> <span style="color:#c00000">{{item.cannotTake}}</span></p><h4>FAQs:</h4><div v-for="faq in item.faq" :key="faq.q" class="script-card"><b>{{faq.q}}</b><p>{{faq.a}}</p></div></div></details></div></section></template>
  <template v-else-if="selectedView==='objections'"><section id="objections-area" class="card"><header class="card-hdr">🛡️ Objection Handling Guide</header><div class="card-body"><details v-for="item in objections" :key="item.obj" class="acc-item"><summary class="acc-hdr">🛡️ “{{item.obj}}”<span class="acc-icon">▼</span></summary><div class="acc-body"><div class="script-card"><div class="sc-title">✅ Recommended Response</div><div class="sc-text" style="white-space:pre-line">{{item.response}}</div><div class="agent-tip">💡 <strong>Key Strategy:</strong> {{item.tip}}</div><button class="copy-btn" @click="copyText(item.response)">📋 Copy</button></div></div></details></div></section></template>
  <template v-else-if="selectedView==='branches'"><div class="cc-branch-grid"><article v-for="branch in branches" :key="branch.code" class="cc-branch-card"><header><span>🏥</span><div><strong>{{branch.name}}</strong><small>{{branch.city}} · {{branch.code}}</small></div></header><p>📍 {{branch.address}}</p><p>📞 {{branch.phone}}</p><p>🕐 {{branch.hours}}</p><footer><a :href="branch.maps" target="_blank" rel="noopener">Open map</a><button @click="copyText(`${branch.name} (${branch.city})\n${branch.address}\n${branch.phone}\n${branch.hours}\n${branch.maps}`)">Copy details</button></footer></article></div><p v-if="copyNotice" class="cc-success">{{copyNotice}}</p></template>
  <template v-else-if="selectedView==='doctors'"><section class="cc-card"><header>👩‍⚕️ Doctor Directory <button @click="loadDoctors">↻ Refresh</button></header><div class="cc-queue-filters"><label>Branch<select v-model="doctorBranch" @change="loadDoctors"><option value="">Select branch</option><option v-for="branch in doctorBranches" :key="branch">{{branch}}</option></select></label></div><p v-if="doctorLoading">Loading branch staff…</p><p v-if="doctorError" class="cc-error">{{doctorError}}</p><p class="cc-note">Staff availability follows the selected branch’s live appointment schedule.</p><div v-for="group in [...new Set(doctorRows.map(x=>x.designation||x.role||'Clinical staff'))]" :key="group"><h3>{{group}}</h3><div class="cc-doctor-grid"><article v-for="doctor in doctorRows.filter(x=>(x.designation||x.role||'Clinical staff')===group)" :key="doctor.id"><strong>👨‍⚕️ {{doctor.name}}</strong><small>{{doctor.designation||doctor.role||'Clinical staff'}}</small><small>{{(doctor.practitioners||[]).join(', ')}}</small></article></div></div><p v-if="!doctorLoading&&!doctorError&&!doctorRows.length">No staff is available for this branch.</p></section></template>
  <template v-else-if="selectedView==='followup'&&!detail"><p class="cc-status-line">{{loading?'Searching…':rows.length?'Select the client to start the follow-up form.':'Search by mobile number, client name or Lead ID.'}}</p><CCDataTable :columns="columns" :rows="rows" :busy="loading"><template #actions="{row}"><button class="cc-primary" @click="openDetail(row)">Open Follow-Up Form</button></template></CCDataTable><CCPager :page="page" :pages="pages" :busy="loading" @change="load" /></template>
  <template v-else-if="selectedView==='followup'&&detail"><p v-if="detailLoading" role="status">Loading lead…</p><p v-else-if="detailError" class="cc-error" role="alert">{{detailError}}</p><CCLeadWorksheet v-else :lead="detail" :manager="contactManager" :busy="savingFollowup" :error="actionError" :notice="actionNotice" v-model:draft="leadDraft" v-model:followup="followup" v-model:categories="selectedCategories" v-model:interests="selectedInterests" @save="saveFollowup" @back="closeDetail" @start-call="startCall" @stop-call="openPhone" /></template>
  </div></main></div>
  <CCConsultationBooking ref="booking" @saved="appointmentSaved" />
  <dialog ref="dialog" class="modal-box cc-summary-modal"><template v-if="summaryLead"><h2 class="modal-title">Lead Summary — {{summaryLead.lead_name||summaryLead.name}}</h2><div class="form-section">👤 Lead Owner: {{summaryLead.lead_owner||'Unassigned'}} · 🆔 {{summaryLead.name}}</div><div class="form-grid"><div v-for="[label,value] in [['ID',summaryLead.name],['Name',summaryLead.lead_name],['Phone',maskPhone(summaryLead.mobile_no)],['Age / Gender',(summaryLead.age||'—')+' / '+(summaryLead.gender||'—')],['Area',summaryLead.city],['Branch',summaryLead.branch||summaryLead.lead_assign_to_branch],['Source',summaryLead.source],['Assigned To',summaryLead.lead_owner],['Status',summaryLead.custom_cc_stage],['Sub-status',summaryLead.custom_cc_sub_status],['Categories',summaryLead.custom_treatment_interests],['Calls Made',summaryLead.custom_call_count||0],['Next Follow-up',summaryLead.custom_next_followup_date],['Portal Status',summaryLead.status],['Posting Date',summaryLead.custom_posting_date],['Created On',summaryLead.creation],['Last Updated',summaryLead.modified],['Conclusion',summaryLead.custom_conclusion_remark],['Remarks',String(summaryLead.custom_remarks||'').replace(/\[CC_PROFILE_V1\][\s\S]*?\[\/CC_PROFILE_V1\]/g,'').trim()]]" :key="label"><strong>{{label}}:</strong> {{value||'—'}}</div></div><div class="btn-row"><button class="btn btn-n btn-sm" @click="dialog.close();openDetail(summaryLead)">📞 Open Follow-Up Form</button><RouterLink class="btn btn-gy btn-sm" :to="{name:'convox-history',params:{leadId:summaryLead.name}}" @click="dialog.close()">🎧 Call history</RouterLink><RouterLink class="btn btn-gy btn-sm" :to="{name:'cc-appointments',query:{lead:summaryLead.name}}" @click="dialog.close()">📅 Appointments</RouterLink><button class="btn btn-gy btn-sm" @click="dialog.close()">Close</button></div></template></dialog>
  <dialog ref="createDialog" class="cc-create-dialog" aria-labelledby="create-title"><form @submit.prevent="createLead"><header><div><h2 id="create-title">Add new lead</h2><p class="cc-note">Lead is checked for a duplicate mobile number before it is created.</p></div><button type="button" aria-label="Close" @click="createDialog?.close()">×</button></header><div class="cc-create-grid"><label>Client name<input v-model="createForm.first_name" required></label><label>Mobile number<input v-model="createForm.mobile_no" type="tel" required></label><label>Email<input v-model="createForm.email_id" type="email"></label><label>Age<input v-model="createForm.age" type="number" min="1"></label><label>Gender<select v-model="createForm.gender"><option value="">Select</option><option>Female</option><option>Male</option><option>Other</option></select></label><label>City<input v-model="createForm.city"></label><label>Lead source<input v-model="createForm.source"></label><label>Branch<input v-model="createForm.branch"></label><label>Interested in<input v-model="createForm.enquired_for"></label><label class="cc-wide">Remarks<textarea v-model="createForm.custom_remarks" rows="3"></textarea></label></div><p v-if="createError" class="cc-error" role="alert">{{createError}}</p><footer><button type="button" @click="createDialog?.close()">Cancel</button><button class="cc-primary" :disabled="createBusy">{{createBusy?'Creating…':'Create lead'}}</button></footer></form></dialog>
</section>
</template>
